public class Main {
	public static void main(String[] args) {
		Scanner s2 = new Scanner(System.in);
		int len1 = s2.nextInt();
		int arr = s2.nextInt();

		if (len1 >= arr) {
			System.out.println(solutionA(len1, arr));
		} else if (len1 < arr) {
			System.out.println(solutionA(arr, len1));
		}
	}

	private static int solutionA(int comp, int antena) {
		int result;
		while ((result = comp % antena) != 0) {
			comp = antena;
			antena = result;
		}
		return antena;
	}
}

import java.util.Scanner;

public class Main {

	public static void main(String[] abs) {
		Scanner scan = new Scanner(System.in);
		int max = scan.nextInt();
		int rate = scan.nextInt();
		int cd = 0;
		if (max == rate) {
			cd = max;
		} else {
			cd = find(max, rate, cd);
		}
		System.out.println(cd);
		scan.close();
	}

	public static int find(int max, int rate, int cd) {
		if (max < rate) {
			int temp = max;
			max = rate;
			rate = temp;
		}
		max %= rate;
		for (int sam = max; true; sam--) {
			if (max % sam == 0 && rate % sam == 0) {
				cd = sam;
				break;
			}
		}
		return cd;
	}
}

