import java.util.Scanner;

public class Main {
	public static void main (String [] args) {
		Scanner dist = new Scanner (System.in);

		//２つの自然数入力
		int cal = dist.nextInt();
		int now = dist.nextInt();
		dist.close();

		int d;


		if ( cal == now) {
			d = cal;
		} else {
			if (cal > now) {
				int rec = cal % now;
				d = helper(now,rec);
			}else {
				int rec = now % cal;
				 d = helper(cal,rec);
			}
		}

		System.out.println(d);

	}

	//最大公約数を求める
	public static int helper(int cal, int now) {

		int rec = Math.min(cal, now);

		for (int more = rec; more >= 1; more--) {
			if (cal % more == 0 && now % more == 0) {
				return more;
			}
		}

		return 1;
	}
}

