public class Main{

    public static void main(String[] args)throws IOException{
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String[] cst = reader.readLine().split(" ");
        int ts = Integer.parseInt(cst[0]);
        int ss = Integer.parseInt(cst[1]);
        System.out.println(isBlandrome(ts, ss));
    }

    public static int  isBlandrome(int max, int strAry){
        int scanner;
        if(max < strAry){
            int list;
            list = max;
            max = strAry;
            strAry = list;
        }

        while(strAry > 0){
            scanner = max % strAry;
            max = strAry;
            strAry = scanner;
        }
        return max;
    }

}

