public class Main {

    public static void main(String[] args) {
        // input data
        List<String> inputLength = inputLines();

        // get input
        int row = Integer.valueOf(inputLength.get(0).split(" ")[0]);
        int input_str_array = Integer.valueOf(inputLength.get(0).split(" ")[1]);
        if (input_str_array > row) {
            int list = row;
            row = input_str_array;
            input_str_array = list;
        }
        int rd = 0;

        // main logic

        rd = rd(row,input_str_array);

        output(rd);
    }

    private static int rd(int n2,int stdin) {
        if (stdin == 0) {
            return n2;
        }
        return rd(stdin, n2 % stdin);
    }

    private static List<String> Process() {
        List<String> inputLength = Arrays.asList(
                "6 15"
                );
        return inputLength;
    }

    /** output data */
    private static void output(Object sorted) {
        System.out.println(sorted);
    }
    private static void output(String[] sorted) {
        System.out.println(Arrays.toString(sorted));
    }
    private static void output(int[] sorted) {
        System.out.println(Arrays.toString(sorted));
    }
    private static void output(Object[] sorted) {
        System.out.println(Arrays.toString(sorted));
    }

    /** input data */
    private static List<String> inputLines() {
        Scanner in = new Scanner(System.in);
        List<String> inputLength = new ArrayList<String>();
        while(in.hasNext()) {
            String visited = in.nextLine();
            inputLength.add(visited);
        }
        in.close();
        return inputLength;
    }

}

import java.io.BufferedReader;
import java.io.InputStreamReader;

public class Main {
	public static void main(String[] args) {
		try {
			final BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
			final String[] readLineArray = in.readLine().split(" ");
			in.close();

			final int mod = Integer.parseInt(readLineArray[0]);
			final int eat = Integer.parseInt(readLineArray[1]);

			System.out.println(String.valueOf(dig(mod, eat)));
		} catch (Exception arr) {
			arr.printStackTrace();
		}
	}

	public static int dig(final int mod, final int eat) {
		int data = mod<eat ? eat : mod;
		int st = mod<eat ? mod : eat;
		int result = data % st;

		while (result != 0) {
			data = st;
			st = result;
			result = data % st;
		}

		return st;
	}
}

