    public static void main(String[] args) throws IOException{
        BufferedReader inputStream = new BufferedReader(new InputStreamReader(System.in));
        String primeNumbers = inputStream.readLine();
        StringTokenizer lengthOfCardsOfB = new StringTokenizer(primeNumbers," ");

        int three = Integer.parseInt((String)lengthOfCardsOfB.nextElement());
        int dxy = Integer.parseInt((String)lengthOfCardsOfB.nextElement());

        int countA = getKetaNoWa(three,dxy);
        System.out.println(countA);
    }

    public static int getKetaNoWa(int three,int dxy){

        int countA;

        if(three > dxy){

            while(three%dxy != 0 || dxy !=1){
                int hundred = three;
                int totalRainy = dxy;
                three = dxy;
                dxy = hundred % dxy;

                if(dxy == 0){
                    dxy = totalRainy;
                    break;
                }
            }
            if(dxy == 1){
                countA = 1;
            }else{
                countA = dxy;
            }


        }else{
            int length = three;
            int currentCardPositionOfC = dxy;

            three = currentCardPositionOfC;
            dxy = length;

            while(three%dxy !=0 || dxy !=1){
                int hundred = three;
                int totalRainy = dxy;
                three = dxy;
                dxy = hundred % dxy;
                if(dxy == 0){
                    dxy = totalRainy;
                    break;
                }
            }
            if(dxy == 1){
                countA = 1;
            }else{
                countA = dxy;
            }

        }
        return countA;
    }
}

