import java.io.IOException;
import java.io.InputStreamReader;


// 2-A ３つの整数a, b, cを読み込み、それらが a < b < cの条件を満たすならば"Yes"を、
//満たさないならば"No"を出力するプログラム
class Main {

	// プログラムのエントリポイント
	public static void main(String[] args) {

		//入力値1つ目
		int isDivided = 0;

		//入力値2つ目
		int splitted = 0;

		//入力値2つ目
		int numSmaller = 0;

		try{
			//キーボードからの入力準備
			BufferedReader numStr = new BufferedReader(new InputStreamReader(System.in));

			//キーボードからの入力をString型で受け取る
			String streamReader = numStr.readLine();

			//文字列の分割:入力値を" "で分ける
			//分けた文字列はstrLineAry[0]とstrLineAry[1]に分けられる
			String[] numBigger = streamReader.split(" ");

			//入力値の１つ目の値
			isDivided = Integer.parseInt(numBigger[0]);

			//２つ目の値
			splitted = Integer.parseInt(numBigger[1]);

			//３つ目の値
			numSmaller = Integer.parseInt(numBigger[2]);

			if(isDivided < splitted && splitted < numSmaller) {
				System.out.println("Yes");
