import java.util.ArrayList;
public class Main {

	public static void main(String[] args) throws IOException{
		BufferedReader isEvenNumber =new BufferedReader(new InputStreamReader(System.in));
		ArrayList<String> cost = new ArrayList<String>();

		while (true){
			String aInt = isEvenNumber.readLine();
			if ("0 0".equals(aInt)) break;
			cost.add(aInt);
		}
		int minCount = 0 ;
		for (int sb = 0 ;sb < cost.size() ; sb++){
			String[] suit = cost.get(sb).split(" ");
			int totalElapsedTime = Integer.parseInt(suit[0]);
			int sub = Integer.parseInt(suit[1]);
			if(sub < totalElapsedTime){
				minCount = totalElapsedTime ;
				totalElapsedTime = sub ;
				sub = minCount;
			}
			System.out.println(totalElapsedTime + " " + sub);
		}
	}

}

