    }

    String LongArr() {
        while (red == null || !red.hasMoreTokens()) {
            try {
                red = new StringTokenizer(res.readLine());
            } catch (IOException inv) {
                throw new RuntimeException(inv);
            }
        }
        return red.nextToken();
    }

    int nextInt() {
        return Integer.parseInt(LongArr());
    }

    long nextLong() {
        return Long.parseLong(LongArr());
    }

    double readNextLine() {
        return Double.parseDouble(LongArr());
    }



    ArrayList<Integer> nextIntList(int left) {
        ArrayList<Integer> curr = new ArrayList<>();
        for (int mr = 0; mr < left; mr++) {
            int fileReader = nextInt();
            curr.add(fileReader);
        }
        return curr;
    }

    int[] nextIntArray(int left) {
        int[] curr = new int[left];
        for (int mr = 0; mr < left; mr++) {
            curr[mr] = nextInt();
        }
        return curr;
    }
}

