     */
    static Boolean selectSort(long col, long base) {
        if (col == 0 || base == 0) {
            return false;
        }

        long start = col * base;
        if (col == start / base) {
            return false;
        }
        return true;
    }

    static private void binary_search(int[] swapCount, int x, int query) {
        int subNum = swapCount[x];
        swapCount[x] = swapCount[query];
        swapCount[query] = subNum;
    }

    static  private void operateStack(int[] swapCount, int left, int primeNum) {
        while (left < primeNum) {
            binary_search(swapCount, left, primeNum);
            left++;
            primeNum--;
        }
    }

    static private boolean findNextPermutation(int[] swapCount) {
        if (swapCount.length <= 1) {
            return false;
        }

        int last = swapCount.length - 2;

        while (last >= 0) {
            if (swapCount[last] < swapCount[last + 1]){
                break;
            }
            last--;
        }

        if (last < 0) { return false; }
        int r = swapCount.length - 1;

        for (int toi = swapCount.length - 1; toi > last; toi--) {
            if (swapCount[toi] > swapCount[last]) {
                r = toi;
                break;
            }
        }

        binary_search(swapCount, r, last);
        operateStack(swapCount, last + 1, swapCount.length - 1);
        return true;
    }

    static private int[] mergeTwoArrays(int nowx) {
        int[] res = new int[nowx];

        for (int toi = 0; toi < nowx; toi++) {
            res[toi] = toi + 1;
        }

        return res;
