    }

    static private int binarySearch(int x) {
        return (int)(Math.log(x) / Math.log(2));
    }

    static private long getNearestValue(long orderedList, long nowx) {
        if (orderedList < nowx) { return getNearestValue(nowx, orderedList); }
        if (orderedList % nowx == 0) { return nowx; }
        return getNearestValue(nowx, orderedList%nowx);
    }

