        Scanner max = new Scanner(System.in);
        int m = max.nextInt();
        long sin = 0;

        for(int val = 1; val <= m; val++)
        {
            for(int inputData = 1; inputData <= m; inputData++)
            {
                for(int cell = 1; cell <= m; cell++)
                {
                    if(val == inputData && inputData ==cell)
                    {
                        sin += val;
                    }
                    else
                    {
                        //最大公約数を求める
                        int result = countUp(val,inputData,cell);
                        sin += result;
                    }
                }
            }
        }
        System.out.println(sin);
    }

    public static int countUp(int x,int apple, int searches) {
        if(x < apple)
        {
            int result = x;
            x = apple;
            apple = result;
        }
        int cur = 0;
        while(( cur = x % apple) != 0)
        {
            x = apple;
            apple = cur;
        }

        if(apple < searches)
        {
            int result = apple;
            apple = searches;
            searches = result;
        }
        while((cur = apple % searches) != 0)
        {
            apple = searches;
            searches = cur;
        }
        return searches;
    }
}

