	public static void main(String[] args) {
		// TODO 自動生成されたメソッド・スタブ
		Scanner str2 = new Scanner(System.in);

		int m = str2.nextInt();
		int size = 0;

		for(int maxSubtruction = 1; maxSubtruction <= m; maxSubtruction++) {
			for(int taro = 1; taro <= m; taro++) {
				for (int sub = 1; sub <= m; sub++) {
					size = size + getString(maxSubtruction, taro, sub);
				}
			}
		}

		System.out.println(size);
	}

	public static final int getString(final int... swap) {
	    final int console = swap.length;
	    int dist = getKetaNoWa(swap[0], swap[1]);    //gcd(a, b) は以前作ったもの
	    for (int maxSubtruction = 1; maxSubtruction < console - 1; maxSubtruction++) {
	        dist = getKetaNoWa(dist, swap[maxSubtruction + 1]);       //gcd(a, b) は以前作ったもの
	    }
	    return dist;
	}

	private static int getKetaNoWa(int maxSubtructionIndex, int y) {
        int cCards = Math.max(maxSubtructionIndex, y);
        int cCardMaxLen = Math.min(maxSubtructionIndex, y);

        // 大きい方から小さい方を割った余を求める
        int dNum = cCards % cCardMaxLen;

        // 割り切れていれば、それを返す
        if (dNum == 0) {
            return cCardMaxLen;
        }
        // 割り切れなければ再帰的に自信を呼び出す
        dNum = getKetaNoWa(cCardMaxLen, dNum);

        return dNum;
    }
}

