public class Main {

	public static void main(String[] args) throws Exception {
		Scanner sc = new Scanner(System.in);
		int sArray = sc.nextInt();
		Map<String, Integer> mod = new TreeMap<>();
		int stack = 0;
		for(int minAbs=0;minAbs<sArray;minAbs++){
