		Scanner card = new Scanner(System.in);
		List<String> data = new ArrayList<String>();
		List<String> init_time = new ArrayList<String>();
		List<Integer> capacity = new ArrayList<Integer>();

		int m = card.nextInt();
		for(int right=0;right<m;right++) {
			data.add(card.next());
		}

		Collections.sort(data);

		int qTime = 0;
		boolean penaltys = false;
		init_time.add(data.get(0));

		for(int right =1; right<m; right++) {
			if(data.get(right).equals(data.get(right-1))) {
				penaltys = true;
				qTime++;
				if(right==m-1) {
					capacity.add(qTime);
				}
			}else if((data.get(right).equals(data.get(right-1)))==false){
				init_time.add(data.get(right));
				capacity.add(qTime);
				qTime =0;
			}
		}

		if(!penaltys) {
			capacity.add(qTime);
		}

		int problem = 0;
		int itemsList = 0;
		List<Integer> max = new ArrayList<Integer>();
		List<String> inS = new ArrayList<String>();

		for(int count:capacity) {
			if(problem==0) {
				max.add(capacity.get(0));
				inS.add(init_time.get(0));
