				if(max.get(itemsList)==count) {
					inS.add(init_time.get(problem));
				}else if(max.get(itemsList)<count) {
					max.clear();
					inS.clear();
					max.add(capacity.get(problem));
					inS.add(init_time.get(problem));
				}
			}
			problem++;
