public class Main {

	public static void main(String[] args) {

		Scanner ans2 = new Scanner(System.in);
		int m = ans2.nextInt();

		String right[] = new String[m];
		ans2.nextLine();

		for (int names = 0; names < m; names++) {
			right[names] = ans2.nextLine();
		}

		Arrays.sort(right);

		int remove = 1;
		Map<String, Integer> end = new HashMap<>();

		for (int names = 0; names < m - 1; names++) {
			if (right[names].equals(right[names + 1])) {
				remove++;
			} else {
				end.put(right[names], remove);
				remove = 1;
			}
		}

		if (right[m - 2].equals(right[m - 1])) {
			end.put(right[m - 1], remove);
		} else {
			end.put(right[m - 2], remove);
			end.put(right[m - 1], 1);
		}

		int sheet = 0;

		ArrayList<String> inputLen = new ArrayList<>();

		for (String distance : end.keySet()) {
			if (end.get(distance) > sheet)
				sheet = end.get(distance);
		}

		for (String distance : end.keySet()) {
			if (end.get(distance) == sheet)
				inputLen.add(distance);
		}

		Collections.sort(inputLen);
		for (String sum : inputLen) {
			System.out.println(sum);
		}

		ans2.close();

	}
}

