class FastReader {
    BufferedReader r;
    StringTokenizer scanner;

    FastReader() {
        r = new BufferedReader(new InputStreamReader(System.in));
        scanner = new StringTokenizer("");
    }

    String next() throws IOException {
        while (!scanner.hasMoreTokens() ) { 
            scanner = new StringTokenizer(r.readLine()); 
        }
        return scanner.nextToken();
    }

    int nextIntArr() throws IOException { 
        return Integer.parseInt(next()); 
    }

    double nextChar() throws IOException { 
        return Double.parseDouble(next());
    }

    long nextLongArr() throws IOException { 
        return Long.parseLong(next()); 
    }

    String nextStr() throws IOException { 
        return r.readLine(); 
    }

    void close() throws IOException { 
        r.close(); 
    }
}

