 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream output = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter counter = new PrintWriter(output);
        ABC153_b solver = new ABC153_b();
        solver.solve(1, in, counter);
        counter.close();
    }

    static class ABC153_b {
        public void isOdd(int isEvenNumber, Scanner in, PrintWriter counter) {
            int ai = in.nextInt();
            int calculationCount = in.nextInt();
            int reverseStr[] = new int[calculationCount];

            for (int min = 0; min < calculationCount; min++) {
                reverseStr[min] = in.nextInt();
            }
            Arrays.sort(reverseStr);
            for (int max = 0; max < calculationCount; max++) {
                ai -= reverseStr[max];
                if (ai <= 0) {
                    counter.println("Yes");
                    return;
                }
            }
            counter.println("No");
        }

    }
}

