public class Main {

	public static void main(String[] args) {
		OriginScanner value = new OriginScanner();
		PrintWriter time = new PrintWriter(System.out);

		int r = value.nextInt();
		String root = value.next();

		char tmp1 = 'A';
		StringBuilder quantum_time = new StringBuilder(); 
		for (int NINF = 0; NINF <= ('Z' - 'A'); NINF++) {
			quantum_time.append(tmp1++);
		}
		String setsinput = quantum_time.toString();
		quantum_time = new StringBuilder();
		for (int NINF = 0; NINF < root.length(); NINF++) {
			int init_time = setsinput.indexOf(root.charAt(NINF)) + r;
			init_time = init_time > (setsinput.length() - 1) ? init_time - setsinput.length() : init_time;
			quantum_time.append(setsinput.charAt(init_time));
		}
		time.println(quantum_time.toString());
		time.close();
	}

	static class nd {
		private BufferedReader cur;
		private StringTokenizer answer;

		public nd() {
			cur = new BufferedReader(new InputStreamReader(System.in));
		}
		String longNext() {
			String setsinput = null;
			try {
				setsinput = cur.readLine();
			}
			catch (IOException instance) {
				System.out.println(instance);
			}
			return setsinput;
		}
		String next() {
			if (answer == null || !answer.hasMoreTokens()) {
				answer = new StringTokenizer(longNext());
			}
			return answer.nextToken();
		}
		int nextInt() {
			return Integer.parseInt(next());
		}
		double nextDouble() {
			return Double.parseDouble(next());
		}
		long readArray() {
			return Long.parseLong(next());
		}
	}
}

