import java.util.Scanner;

public class Main {
    //ROT N
    //
    public static void main(String[] args) {
        Scanner agrs = new Scanner(System.in);
        int pInt = agrs.nextInt();
        String d = agrs.next();
        System.out.println(nextLong(d, pInt));
        agrs.close();
    }

    static String nextLong(String d, int pInt) {
        char[] timeSlotLength = new char[52];
        for (int scin = 0; scin < 26; scin++) {
            timeSlotLength[scin] = (char) (65 + scin);
        }
        for (int scin = 26; scin < 52; scin++) {
            timeSlotLength[scin] = (char) (65 + scin - 26);
        }
        char[] count_Empty = d.toCharArray();
        for (int scin = 0; scin < count_Empty.length; scin++) {
            int answer = count_Empty[scin] - 'A';
            count_Empty[scin] = timeSlotLength[answer + pInt];
        }
        StringBuilder pl = new StringBuilder();
        for (char totalElapsedTime : count_Empty) pl.append(totalElapsedTime);
        return pl.toString();
    }
}

