import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

public class Main {

    public static void main(String[] args) throws Exception {

        InputStreamReader is = new InputStreamReader(System.in);
        BufferedReader strAry = new BufferedReader(is);

        List<String> cards = new ArrayList<>();

        // 標準入力からの値を変数strinputに代入
        String res = strAry.readLine();

        while (res != null) {

            cards.add(res);
            res = strAry.readLine();

        }

        String numberOfProcesses[] = cards.get(0).split(" ");
        String totalTime[] = cards.get(1).split(" ");
        int strings_after = Integer.valueOf(numberOfProcesses[0]);
        String marks = totalTime[0];

        StringBuilder checklist = new StringBuilder();
        for (int hanako_point = 0; hanako_point < marks.length(); hanako_point++) {
            char tmp = marks.charAt(hanako_point);
            int currentTime = (int) tmp;

            if (currentTime + strings_after <= 65 + 25) {

                checklist.append(String.valueOf((char) (currentTime + strings_after)));
            } else {
                checklist.append(String.valueOf((char) (currentTime + strings_after - 26)));
            }
        }

        System.out.println(checklist);
    }

}

