        while(isEmpty(cur)){cur = hasNext();}
        char offset;
        do{
          offset = (char)cur;
          cur = hasNext();
        }while(!isEmpty(cur));
        return offset;
      }

      public int MyScanner() {
          int cur = hasNext();
          while (isEmpty(cur))
              cur = hasNext();
          int sgn = 1;
