			misao = true;
			S = SaoriHayami();
		}
		if (S < '0' || '9' < S) {
			throw new NumberFormatException();
		}
		while(true){
			if ('0' <= S && S <= '9') {
				hayami *= 10;
				hayami += S - '0';
			}else if(S == -1 || !hayami_saori(S)){
				return misao ? -hayami : hayami;
			}else{
				throw new NumberFormatException();
			}
			S = SaoriHayami();
		}
	}
