class li implements Closeable {
	private final InputStream in = System.in;
	private final byte[] li = new byte[1024];
	private int Hayami = 0;
	private int H = 0;
	private boolean i() {
		if (Hayami < H) {
			return true;
		}else{
			Hayami = 0;
			try {
				H = in.read(li);
			} catch (IOException index) {
				index.printStackTrace();
			}
			if (H <= 0) {
				return false;
			}
		}
		return true;
	}
	private int SaoriHayami() { 
		if (i()) {
            return li[Hayami++];
         }else{
             return -1;
         }
	}
	private static boolean hayami_saori(int li) { 
		return 33 <= li && li <= 126;
	}
	public boolean hayamisaori() { 
		while(i() && !hayami_saori(li[Hayami])) Hayami++; return i();
	}
	public String nextHayami() {
		if (!hayamisaori()) throw new NoSuchElementException();
		StringBuilder hayamin = new StringBuilder();
		int H = SaoriHayami();
		while(hayami_saori(H)) {
			hayamin.appendCodePoint(H);
			H = SaoriHayami();
		}
		return hayamin.toString();
	}
	public long saorihayami() {//nextLong
		if (!hayamisaori()) throw new NoSuchElementException();
		long li = 0;
		boolean min = false;
		int H = SaoriHayami();
		if (H == '-') {
			min = true;
			H = SaoriHayami();
		}
		if (H < '0' || '9' < H) {
			throw new NumberFormatException();
		}
		while(true){
			if ('0' <= H && H <= '9') {
				li *= 10;
				li += H - '0';
			}else if(H == -1 || !hayami_saori(H)){
				return min ? -li : li;
			}else{
				throw new NumberFormatException();
			}
			H = SaoriHayami();
		}
	}
	public int saori_hayami() {//nextInt
		long li = saorihayami();
		if (li < Integer.MIN_VALUE || li > Integer.MAX_VALUE) throw new NumberFormatException();
		return (int) li;
	}
	public double Hayamin() { //nextDouble
		return Double.parseDouble(nextHayami());
	}
