class FastScanner {
    private final InputStream in = System.in;
    private final byte[] testNumber = new byte[1024];
    private int builder = 0;
    private int inbuf = 0;
    private boolean skipUnprintable() {
        if (builder < inbuf) {
            return true;
        }else{
            builder = 0;
            try {
                inbuf = in.read(testNumber);
            } catch (IOException e) {
                e.printStackTrace();
            }
            if (inbuf <= 0) {
                return false;
            }
        }
        return true;
    }
    private int readHead() { if (skipUnprintable()) return testNumber[builder++]; else return -1;}
    private static boolean execute(int third) { return 33 <= third && third <= 126;}
    public boolean isPrintableByte() { while(skipUnprintable() && !execute(testNumber[builder])) builder++; return skipUnprintable();}
    public String nextALong() {
        if (!isPrintableByte()) throw new NoSuchElementException();
        StringBuilder s = new StringBuilder();
        int bufLength = readHead();
        while(execute(bufLength)) {
            s.appendCodePoint(bufLength);
            bufLength = readHead();
        }
        return s.toString();
    }

    public int nextAInt() {
    	return Integer.parseInt(nextALong());
    }

    public long _nextInt() {
    	return Long.parseLong(nextALong());
    }
}

