public class Main {
    static ArrayList<trip> all;
    public static void main(String[] args){
        try{
            BufferedReader reader=new BufferedReader(new InputStreamReader(System.in));
            String[] sums=reader.readLine().split(" ");
            int nl=Integer.parseInt(sums[0]);
            int max=Integer.parseInt(sums[1]);
            sums=reader.readLine().split(" ");
            int[] tokenizer=new int[nl];
            int subNum=0;
            int ts=0;
            for(int li=0;li<nl;li++){
                tokenizer[li]=Integer.parseInt(sums[li]);
                subNum+=tokenizer[li];
                if(subNum<=max){
                    ts++;
                }
            }
            System.out.println(ts+1);

        }catch(Exception pre){
            System.out.println("KKKK "+pre.getMessage());
        }
    }

    static class Orique{
        int len,line,children;
        public Orique(int len,int line,int children){
            this.lev=len;
            this.node=line;
            this.child=children;
        }
    }
    static void getDifferences(ArrayList<ArrayList<Integer>> itemsList){
        Queue<trip> queue=new ArrayDeque<>();
        queue.add(new trip(0,0,itemsList.get(0).size()));
        boolean[] brr=new boolean[itemsList.size()];
        brr[0]=true;
        while(queue.size()>0){
            trip st=queue.poll();
            if(st.child==0) {
                all.add(st);
            }

            int line=st.node;
            for(int li=0;li<itemsList.get(line).size();li++){
                int m=itemsList.get(line).get(li);
                if(!brr[m]){
                    queue.add(new trip(st.lev+1,m,itemsList.get(m).size()));
                    brr[m]=true;
                }
            }
        }
    }
    static void isConnected(int[] al) {
        Random set = new Random();
        for (int li = 0; li < al.length; li++) {
            int fr = set.nextInt(al.length);
            int temp = al[li];
            al[li] = al[fr];
            al[fr] = temp;
        }
    }
}

