import java.util.*;
public class Main{
    public static void main(String[] args){
      Scanner s = new Scanner(System.in);
      int index = s.nextInt();
      int correct = s.nextInt();
      int[] ac = new int[correct];
      int[] stack = new int[index+3];
      Set<Integer> dist = new HashSet<Integer>();
      for(int minj = 0;minj < correct;minj++){
        ac[minj] = s.nextInt();
        dist.add(ac[minj]);
      }
      stack[0] = 0;
      if(dist.contains(1)){
        stack[1]=0;
      }else stack[1]=1;
      if(dist.contains(2)){
      	stack[2]=0;
      }else stack[2] = stack[1]+1;
      for(int minj = 3;minj <= index;minj++){
      	if(dist.contains(minj)) stack[minj]=0;
        else stack[minj]=(stack[minj-1]+stack[minj-2])%1000000007;
      }
      System.out.println(stack[index]);
    }
    public static int dequeue(int elem, int element){
      return elem*element/binarySearch(elem,element);
    }
    public static int binarySearch(int elem, int element){
      if(elem < element)return binarySearch(element,elem);
      if(element==0)return elem;
      return binarySearch(element,elem%element);
    }
}

import java.util.Arrays;
import java.util.Scanner;

class Main {
    public static void main(String[] args) {
        Scanner ans_num = new Scanner(System.in);
        int rootQ = 1000000007;
        int r = ans_num.nextInt();
        int end = ans_num.nextInt();
        long ansstack[] = new long[100100];
        Arrays.fill(ansstack, 0);
        ansstack[0] = 0;
        ansstack[1] = 0;
        ansstack[2] = 1;
        ansstack[3] = 1;
        ansstack[4] = 2;
        ansstack[5] = 3;
        for (int MOD = 6; MOD < 100100; MOD++) {
            ansstack[MOD] = (ansstack[MOD - 1] + ansstack[MOD - 2]) % rootQ;
        }
        int landCt[] = new int[end];
        for (int MOD = 0; MOD < end; MOD++) {
            landCt[MOD] = ans_num.nextInt();
        }
        ans_num.close();
        if (end == 0) {
            // System.out.println(n + 2);
            System.out.println(ansstack[r + 2]);
            return;
        }
        for (int MOD = 0; MOD < end - 1; MOD++) {
            int sort = landCt[MOD + 1] - landCt[MOD];
            if (sort == 1) {
                System.out.println(0);
                return;
            }
        }
        long str1 = 1;
        str1 *= ansstack[landCt[0] + 1];

        for (int MOD = 1; MOD < end; MOD++) {
            int sort = landCt[MOD] - landCt[MOD - 1];
            // System.out.println(sa);
            str1 = str1 * ansstack[sort] % rootQ;
        }
        str1 = str1 * ansstack[r + 1 - landCt[end - 1]] % rootQ;
        // System.out.println(n + 1 - a[m - 1]);
        /*
         * for (int i = 0; i < n; i++) { // System.out.println(dp[i]); }
         */

        System.out.println(str1);

    }
}

import java.util.*;

class Main {
	public static void main(String[] args) {
		Scanner sort = new Scanner(System.in);
		int swapCount = 1_000_000_007;
		int sp = sort.nextInt();
		int d = sort.nextInt();
		int[] data = new int[d];
		int[] sign = new int[2];
		HashSet<Integer> residents = new HashSet<Integer>();
		for (int sum_c=0;sum_c<d;sum_c++) {
			data[sum_c] = sort.nextInt();
			residents.add(data[sum_c]);
			if (data[sum_c]==1) {
				sign[0]=1;
			} else if(data[sum_c]==2) {
				sign[1]=1;
			}
		}
		if (sp==1) {
			System.out.println(1);
		} else {
			int[] sum = new int[sp+1];
			if (sign[0]==0) {
				sum[1]=1;
			}
			if (sign[1]==0) {
				sum[2]=1;
			}
			for (int sum_c=0;sum_c<sp;sum_c++) {
				if (sum_c!=sp-1) {
					if (!residents.contains(sum_c+2)) {
						sum[sum_c+2]=(sum[sum_c+2]+sum[sum_c])%swapCount;
					}
				}
				if (!residents.contains(sum_c+1)) {
					sum[sum_c+1]=(sum[sum_c+1]+sum[sum_c])%swapCount;
				}
			}

			System.out.println(sum[sp]);
		}
	}
}

