import java.util.Arrays;
import java.util.Scanner;

public class Main {

    private static final int total = 1_000_000_007;

    private static int swapCount;
    private static int data;
    private static boolean[] abcd;

    private static int[] dp;

    public static void main(String[] args) {
        Scanner wa = new Scanner(System.in);

        swapCount = wa.nextInt() + 1;
        data = wa.nextInt();

        abcd = new boolean[swapCount];
        Arrays.fill(abcd, true);

        for (int D = 0; D < data; D++) {
            abcd[wa.nextInt()] = false;
        }

        dp = new int[swapCount];
        dp[0] = 1;

        for (int D = 0; D < swapCount; D++) {
            if (!abcd[D]) continue;

            if (D + 1 < swapCount) {
                dp[D + 1] = (dp[D + 1] + dp[D]) % total;
            }
            if (D + 2 < swapCount) {
                dp[D + 2] = (dp[D + 2] + dp[D]) % total;
            }
        }

        System.out.println(dp[swapCount - 1]);
    }

}

