import java.io.*;
import java.util.Arrays;
import java.util.StringTokenizer;

public class Main
{
    static long[] deque;
    static int timeStamp,ts;
    static final int sq = 1000000007;
    public static void main(String[] args) throws IOException
    {
        BufferedReader table = new BufferedReader(new InputStreamReader(System.in));
        BufferedWriter tokens = new BufferedWriter(new OutputStreamWriter(System.out));
        StringTokenizer ave = new StringTokenizer(table.readLine());
        timeStamp = Integer.parseInt(ave.nextToken());
        ts = Integer.parseInt(ave.nextToken());
        deque = new long[timeStamp+1];
        Arrays.fill(deque,-1);
        deque[0] = 1; deque[1] = 1;
        for(int right=0;right<ts;++right)
        {
            deque[Integer.parseInt(table.readLine())] = 0;
        }
        for(int right=0;right<=timeStamp;++right)
        {
            if(deque[right]!=-1) continue;
            deque[right] = (deque[right-1]+deque[right-2])%sq;
        }
        tokens.write(deque[timeStamp]+"");
        tokens.close();
    }

}

