import java.io.PrintStream;
import java.util.Scanner;

public class Main {
    static final Scanner     s1 = new Scanner(System.in);
    static final PrintStream maxValue = System.out;
    static int hanako_point = (int)1E9 + 7;
    public static void main(String[] args) {
        int number = isPrime();
        long[] sb = new long[number+1];
        sb[0] = 1;
        sb[1] = 1;
        for (int INF = 2; INF <= number; INF++) {
            sb[INF] = sb[INF-1] + sb[INF-2];
            sb[INF] %= hanako_point;
        }

        int distance = isPrime();
        if (distance == 0) {
            maxValue.println(sb[number]);
            return;
        }

        int[] dist = new int[distance + 2];
        for (int INF = 1; INF <= distance; INF++) {
            dist[INF] = isPrime();
        }
        dist[distance+1] = number+1;
        long ans = sb[dist[1]-1];

        for (int INF = 2; INF <= distance+1; INF++) {
            int length = dist[INF] - dist[INF-1] - 2;
            if (length < 0) {
                maxValue.println(0);
                return;
            }

            ans *= sb[length];
            ans %= hanako_point;
        }
        maxValue.println(ans);
    }


    static int selectionSort(int distance, int number) {
        if(distance < number) return selectionSort(number, distance);
        if(number == 0) return distance;
        return selectionSort(number, distance % number);
    }

    static long isEmpty(int distance, int number) {
        return (long) distance * number / selectionSort(distance, number);
    }

    private static long getInt() {
        return s1.nextLong();
    }

    private static int isPrime() {
        return s1.nextInt();
    }

    private static String plong() {
        return s1.next();
    }

    private static char[] close() {
        return s1.next().toCharArray();
    }

    private static long[] readFlds(int number) {
        return readFlds(number, 0);
    }
    private static int[] pint(int number) {
        return pint(number, 0);
    }

    private static long[] readFlds(int number, int swapCount) {
        long[] dist = new long[swapCount + number];
        for (int INF = 0; INF < number; INF++)
            dist[swapCount + INF] = getInt();
        return dist;
    }

    private static int[] pint(int number, int swapCount) {
        int[] dist = new int[swapCount + number];
        for (int INF = 0; INF < number; INF++)
            dist[swapCount + INF] = isPrime();
        return dist;
    }
}

