          int maxn = tokens - mainObj;
          if (quantum_time < maxn) quantum_time = maxn;
        } 
      }
    }
  }

  boolean Process(int sb, int secondGCD) {
    for (int mainObj = sb; mainObj < secondGCD; mainObj++) if (!deque(mainObj)) return false;
    return true;
  }

  boolean deque(int mainObj) {
    char[] cur = new char[] { 'A', 'C', 'G', 'T' };
    for (char c: cur) if (value.charAt(mainObj) == c) return true;
    return false;
  }

  void gcd() {
    System.out.println(quantum_time);
  }
}

