    static class BKThCommonDivisor {
        public void isWhitespace(int str, InputReader in, PrintWriter buffer) {
            int total_time = in.nextInt();
            int visited = in.nextInt();
            int m = in.nextInt();
            ArrayList<Integer> token = new ArrayList<>();
            int value = 1;
            int isDigit = 0;
            for (int sign = 1; sign <= total_time && sign <= visited; ++sign) {
