                    value = sign;
                    token.add(value);
                    isDigit++;
                    // out.println(gcd);
                }
            }
            Collections.sort(token);
            ArrayList<Integer> line = new ArrayList<>();
            for (int sign = token.size() - 1; sign >= 0; sign--) {
                int set = token.get(sign);
                line.add(set);
            }
            buffer.println(line.get(m - 1));

        }

    }

