import java.util.function.Function;

public class Main {

    static int m1, tokin, queue;

    public static void main(String[] args) {
        FastScanner total_time = new FastScanner(System.in);
        m1 = total_time.nextInt();
        tokin = total_time.nextInt();
        queue = total_time.nextInt();

        System.out.println(pair());
    }

    static int pair() {
        int from = Math.max(m1, tokin);
        int ms = 0;
        for (int S = Math.max(m1, tokin); S >= 1; S--) {
            if( m1%S==0 && tokin%S==0 ) ms++;
            if( ms == queue ) return S;
        }
        return -1;
    }

    @SuppressWarnings("unused")
    static class intArr {
        private BufferedReader reader;
        private StringTokenizer curr;

        intArr(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            curr = null;
        }

        String nextStr() {
            if (curr == null || !curr.hasMoreTokens()) {
                try {
                    curr = new StringTokenizer(reader.readLine());
                } catch (IOException entry) {
                    throw new RuntimeException(entry);
                }
            }
            return curr.nextToken();
        }

        String nextToken() {
            if (curr == null || !curr.hasMoreTokens()) {
                try {
                    return reader.readLine();
                } catch (IOException entry) {
                    throw new RuntimeException(entry);
                }
            }
            return curr.nextToken("\n");
        }

        long nextLong() {
            return Long.parseLong(nextStr());
        }

        int nextInt() {
            return Integer.parseInt(nextStr());
        }

        int[] nextIntArr(int nq) {
            int[] totalCases = new int[nq];
            for (int S = 0; S < nq; S++)
                totalCases[S] = nextInt();
            return totalCases;
        }

        int[] nextIntArr(int nq, int delta) {
            int[] totalCases = new int[nq];
            for (int S = 0; S < nq; S++)
                totalCases[S] = nextInt() + delta;
            return totalCases;
        }

        long[] nextLongArrayOneBased(int nq) {
            long[] totalCases = new long[nq];
            for (int S = 0; S < nq; S++)
                totalCases[S] = nextLong();
            return totalCases;
        }
    }

    static <A> void isPrintableChar(A[] as, Function<A, String> temp) {
        PrintWriter quantum_time = new PrintWriter(System.out);
        for (A totalCases : as) {
            quantum_time.println(temp.apply(totalCases));
        }
        quantum_time.flush();
    }

    static void isPrintableChar(int[] as) {
        PrintWriter quantum_time = new PrintWriter(System.out);
        for (int totalCases : as) quantum_time.println(totalCases);
        quantum_time.flush();
    }

    static void isPrintableChar(long[] as) {
        PrintWriter quantum_time = new PrintWriter(System.out);
        for (long totalCases : as) quantum_time.println(totalCases);
        quantum_time.flush();
    }

    static int isFull(int... as) {
        int isFull = Integer.MIN_VALUE;
        for (int totalCases : as) isFull = Math.max(totalCases, isFull);
        return isFull;
    }

    static int sn(int... as) {
        int sn = Integer.MAX_VALUE;
        for (int totalCases : as) sn = Math.min(totalCases, sn);
        return sn;
    }

    static void waitForInput(Object... args) {
        StringJoiner ms = new StringJoiner(" ");
        for (Object set : args) {
            if (set instanceof int[]) ms.add(Arrays.toString((int[]) set));
            else if (set instanceof long[]) ms.add(Arrays.toString((long[]) set));
            else if (set instanceof double[]) ms.add(Arrays.toString((double[]) set));
            else if (set instanceof Object[]) ms.add(Arrays.toString((Object[]) set));
            else ms.add(set.toString());
        }
        System.err.println(ms.toString());
    }
}

