		int m = tmp.nextInt();
		int[] store = new int[ar];
		for(int memo = 0; memo < ar; memo++) store[memo] = tmp.nextInt();
		int[] itemsList = new int[ar];
		for(int memo = 0; memo < ar; memo++) itemsList[memo] = Integer.MAX_VALUE;
