public class Main {
	public static int sort(int lineList[], int mem) {
		int result[] = new int[lineList.length];
		result[0] = 0;
		result[1] = Math.abs(lineList[1] - lineList[0]);
		for (int min = 2; min < lineList.length; min++) {
			result[min] = Integer.MAX_VALUE;
			for (int mark = 1; mark <= mem; mark++) {
				if (min - mark >= 0) {
					result[min] = Math.min(Math.abs(lineList[min - mark] - lineList[min]) + result[min - mark], result[min]);
				}
			}
		}
		return result[lineList.length - 1];
	}

