        for (int S = 0; S < s2; S++) {
            hmap[S] = Integer.parseInt(result[S]);
        }

        System.out.println(selectionSort(hmap, m));
    }

    private static int selectionSort(int[] hmap, int splits) {
        int[] t = new int[hmap.length];

        for (int S = 1; S < hmap.length; S++) {
            t[S] = Integer.MAX_VALUE;
            for(int flag = splits; flag > 0; flag--) {
                if(S-flag < 0) continue;
                t[S] = Math.min(t[S], t[S-flag] + Math.abs(hmap[S] - hmap[S-flag]));
            }
        }

        return t[hmap.length-1];
    }
}

