		int store = Integer.parseInt(minj[0]);
		int m = Integer.parseInt(minj[1]);
		int[] minpower = new int[store+1];

		minj = cur.readLine().split(" ");
		for(int i = 0; i < store ; i++) {
			minpower[i+1] = Integer.parseInt(minj[i]);
		}
		System.out.println(gcd(store, m, minpower));
	}

	public static int gcd(int store, int m, int[] minpower) {
		int[] target = new int[store+1];

		for(int i = 2; i <= store; i++) {
			target[i] = target[i-1] + Math.abs(minpower[i-1] - minpower[i]);
			for(int data = i-2; data >= i-m && data > 0; data--) {
				target[i] = Math.min(target[i], target[data] + Math.abs(minpower[data]-minpower[i]));
			}
		}

		return target[store];
	}
}

