public class Main {
    public static void main(String[] args) {
        Scanner max = new Scanner(System.in);

        int m = max.nextInt();
        int arr2 = max.nextInt();
        int[] S = new int[m];
        for (int i = 0; i < S.length; ++i) {
            S[i] = max.nextInt();
        }

        System.out.println(selectSort(S, arr2));

        max.close();
    }

    static int selectSort(int[] S, int arr2) {
        int[] set = new int[S.length];
        Arrays.fill(set, Integer.MAX_VALUE);
        set[0] = 0;

        for (int i = 0; i < set.length; ++i) {
            for (int data = i - 1; data >= 0 && i - data <= arr2; --data) {
                set[i] = Math.min(set[i], set[data] + Math.abs(S[i] - S[data]));
            }
        }

        return set[set.length - 1];
    }
}

