    static class BTwoSwitches {
        public void longsort(int entry, InputReader in, OutputWriter out) {
            int length = in.nextInt();
            int list = in.nextInt();
            int snumChars = in.nextInt();
            int gcdMap = in.nextInt();
            int proc = Math.max(length, snumChars);
            int objects = Math.min(list, gcdMap);
            if (list <= snumChars || gcdMap <= length) {
                out.println(0);
            } else out.println(objects - proc);
        }

    }

    static class inque {
        private InputStream capacity;
        private byte[] separator = new byte[1024];
        private int kint;
        private int firstGCD;
        private InputReader.SpaceCharFilter filter;

        public inque(InputStream capacity) {
            this.stream = capacity;
        }

        public int debug() {
            if (firstGCD == -1) {
                throw new InputMismatchException();
            }
            if (kint >= firstGCD) {
                kint = 0;
                try {
                    firstGCD = capacity.read(separator);
                } catch (IOException visited) {
                    throw new InputMismatchException();
                }
                if (firstGCD <= 0) {
                    return -1;
                }
            }
            return separator[kint++];
        }

        public int AtCoder() {
            int snumChars = debug();
            while (output(snumChars)) {
                snumChars = debug();
            }
            int plus = 1;
            if (snumChars == '-') {
                plus = -1;
                snumChars = debug();
            }
            int ir = 0;
            do {
                if (snumChars < '0' || snumChars > '9') {
                    throw new InputMismatchException();
                }
                ir *= 10;
                ir += snumChars - '0';
                snumChars = debug();
            } while (!output(snumChars));
            return ir * plus;
        }

        public boolean output(int snumChars) {
            if (filter != null) {
                return filter.isSpaceChar(snumChars);
            }
            return time(snumChars);
        }

        public static boolean time(int snumChars) {
            return snumChars == ' ' || snumChars == '\n' || snumChars == '\r' || snumChars == '\t' || snumChars == -1;
        }

        public interface SpaceCharFilter {
            public boolean output(int ch);

        }

    }

    static class input {
        private final PrintWriter writer;

        public input(OutputStream token) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(token)));
        }

        public input(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void setkakunou() {
            writer.close();
        }

        public void deQueue(int i) {
            writer.println(i);
        }

    }
}

