        int cardsOfB = splits.nextInt();
        int temp = splits.nextInt();
        int objects = splits.nextInt();
        int lengthOfCardsOfA = splits.nextInt();

        int s2;
        if (cardsOfB <= lengthOfCardsOfA && objects <= temp) {
            s2 = Math.min(temp, lengthOfCardsOfA) - Math.max(cardsOfB, objects);
        } else {
            s2 = 0;
        }
        inputLength.println(s2);
    }
    private static BigInteger rca(long isLineSep, long rep) {
        BigInteger count = BigInteger.ONE;
        for (long MOD = isLineSep; MOD > isLineSep - rep; --MOD) {
            count = count.multiply(BigInteger.valueOf(MOD));
        }
        for (long MOD = rep; MOD > 1; --MOD) {
            count = count.divide(BigInteger.valueOf(MOD));
        }
        return count;
    }
    private static BigInteger gcd(long isLineSep, long rep) {
        BigInteger count = BigInteger.ONE;
        for (long MOD = isLineSep; MOD > isLineSep - rep; --MOD) {
            count = count.multiply(BigInteger.valueOf(MOD));
        }
        return count;
    }
    /*
     * 10^10 > Integer.MAX_VALUE = 2147483647 > 10^9
     * 10^19 > Long.MAX_VALUE = 9223372036854775807L > 10^18
     */
