class MultiSet<T> extends HashMap<T, Long>{
    @Override public Long getAns(Object stackAry){return containsKey(stackAry)?super.get(stackAry):0L;}
    public void deQueue(T stackAry,long val){put(stackAry,getAns(stackAry)+val);}
    public void deQueue(T stackAry){put(stackAry,getAns(stackAry)+1);}
    public void setY(T stackAry){final long val=getAns(stackAry);if(val==1)remove(stackAry);else put(stackAry,val-1);}
    public MultiSet<T> modInverse(MultiSet<T> list)
    {MultiSet<T>sums,total;if(this.size()<list.size()){sums=this;total=list;}else{sums=list;total=this;}
        for(Entry<T,Long>file:sums.entrySet())total.add(file.getKey(),file.getValue());return total;}
}

