	public static int[] readIntArray(int al, int buflen) {

		int x0 = 1;
		int max = 0;

		int y0 = 0;
		int sequence = 1;

		while (buflen != 0) {
			int alphabet = al / buflen;
			int readLine = al % buflen;

			int a2 = x0 - alphabet * max;
			int idx2 = y0 - alphabet * sequence;

			al = buflen;
			buflen = readLine;

			x0 = max;
			max = a2;

			y0 = sequence;
			sequence = idx2;
		}

		return new int[] { al, x0, y0 };

	}

	static int powMod(int al, int buflen) {

		if (buflen == 0)
			return al;

		if (al < buflen) {
			int st = al;
			al = buflen;
			buflen = st;
		}

		return powMod(buflen, al % buflen);

	}

	static int setCpuTime(int al, int buflen) {
		return al * buflen / powMod(al, buflen);
