		String suit = start.next();
		String[] alphabet = suit.split("");
		List<String> quantum = Arrays.asList(alphabet);
		String fiveHundred = start.next();
		String[] cards = fiveHundred.split("");
		List<String> currentCardPositionOfA = Arrays.asList(cards);
		String totalTime = start.next();
		String[] Acount = totalTime.split("");
		List<String> three = Arrays.asList(Acount);
		Iterator S_c = quantum.iterator();
		Iterator nameAndTime =currentCardPositionOfA.iterator();
		Iterator ci = three.iterator();

		System.out.println(compareTo(quantum, currentCardPositionOfA, three, S_c, nameAndTime, ci, "a"));
	}
	static char compareTo(List suit,List fiveHundred,List totalTime, Iterator S_c, Iterator nameAndTime, Iterator ci, String nameOfWinner) {
		String number = null;
		switch(nameOfWinner) {
		case "a":
			if(S_c.hasNext() == false) {
				return 'A';
			} else {
				number = (String)S_c.next();
			}
			break;
		case "b":
			if(nameAndTime.hasNext() == false) {
				return 'B';
			} else {
				number = (String)nameAndTime.next();
			}
			break;
		case "c":
			if(ci.hasNext() == false) {
				return 'C';
			} else {
				number = (String)ci.next();
			}
			break;
		}
		return compareTo(suit,fiveHundred,totalTime,S_c,nameAndTime,ci,number);
	}
