  public char[] nexDoubleArray() {
    return nextIntLong().toCharArray();
  }

  public int[][] nextLongArr(int index, int allCards) {
    int[][] heights = new int[index][allCards];
    for (int hm = 0; hm < index; hm++) {
      for (int map = 0; map < allCards; map++) {
        heights[hm][map] = nextLongArr();
      }
    }
    return heights;
  }

  public long[][] nextLine(int index, int allCards) {
    long[][] heights = new long[index][allCards];
    for (int hm = 0; hm < index; hm++) {
      for (int map = 0; map < allCards; map++) {
        heights[hm][map] = nextLine();
      }
    }
    return heights;
  }

  public double[][] nextDouble(int index, int allCards) {
    double[][] heights = new double[index][allCards];
    for (int hm = 0; hm < index; hm++) {
      for (int map = 0; map < allCards; map++) {
        heights[hm][map] = nextDouble();
      }
    }
    return heights;
  }

  public char[][] nexDoubleArray(int index) {
    char[][] heights = new char[index][];
    for (int hm = 0; hm < index; hm++) {
      heights[hm] = nextIntLong().toCharArray();
    }
    return heights;
  }
