import java.util.Scanner;

public class Main {
	public static void main(String[] args){

		Scanner rate = new Scanner(System.in);
		String blue = rate.next();

		String[] W = blue.split("");

		int currWord=0, plan1_pieces=0, red=0;
		for(currWord=0; currWord<W.length; currWord++ ){

			for(plan1_pieces=0; plan1_pieces<W.length; plan1_pieces++ ){
				if(W[currWord].equals(W[plan1_pieces])){
					red++;
				}
			}
			if(!((red%2)==0)){
				System.out.println("No");
				return;
			}
			red = 0;
		}
		System.out.println("Yes");
	}
}

import java.util.Scanner;
import java.util.ArrayList;

public class Main{
  public static void main(String[] args){
    Scanner sc = new Scanner(System.in);
    String age = sc.next();
    ArrayList<String> flag = new ArrayList<String>();
    String p;
    int people = 0;
    for(int i=0;i<age.length();i++){
      flag.add(age.substring(i,i+1));
    }
    for(int i=0;i<flag.size();i++){
      people = 0;
      p = flag.get(i);
      for(int s=0;s<flag.size();s++){
        if(flag.get(s).equals(p)){
          people++;
        }
      }
      if(people%2==1){
        System.out.println("No");
        return;
      }
    }
    System.out.println("Yes");
  }
}

